lementById("dSlip"),none=document.getElementById("noSlip");if(d.slip){img.src=d.slip;img.classList.remove("hidden");none.classList.add("hidden")}else{img.classList.add("hidden");none.classList.remove("hidden")}let buttons="";if(o.shipping_status==="shipped")buttons+=form(o.order_id,"delivered","จัดส่งสำเร็จ");if(!["delivered","cancelled","returned"].includes(o.shipping_status))buttons+=form(o.order_id,"cancelled","ยกเลิกคำสั่งซื้อ","outline");document.getElementById("statusForms").innerHTML=buttons;detailModal.classList.add("open");}';
